# generated by gophertunnel b8bd735:
# packet.ResourcePacksInfo{WorldTemplateUUID: uuid.MustParse("00112233-4455-6677-8899-aabbccddeeff"),
# WorldTemplateVersion: "1.2.3"}
V2168_EMPTY = bytes.fromhex("000000007766554433221100ffeeddccbbaa998805312e322e3300")

WORLD_TEMPLATE = v2225.PackIdVersion(
    id=uuid.UUID("00112233-4455-6677-8899-aabbccddeeff"), version=v2225.SemVersion(version="1.2.3")
)

PACK = v2225.PackInfoData(
    pack_id_version=v2225.PackIdVersion(
        id=uuid.UUID("0a0b0c0d-0e0f-1011-1213-141516171819"), version=v2225.SemVersion(version="2.0.0")
    ),
    pack_size=4096,
    content_key="key",
    subpack_name="sub",
    content_identity=v2225.ContentIdentity(identity="cid"),
    has_scripts=True,
    is_ray_tracing_capable=True,
    cdn_url="http://cdn",
)

GOLDENS = [
    pytest.param(
        v975.ResourcePacksInfoPacket(
            resource_pack_required=True,
            has_scripts=True,
            world_template_id_and_version=WORLD_TEMPLATE,
            resource_packs=[PACK],
        ),
        V1001,
        id="v975-with-pack",
    ),
    pytest.param(
        v975.ResourcePacksInfoPacket(world_template_id_and_version=WORLD_TEMPLATE),
        V1001_EMPTY,
        id="v975-empty",
    ),
    pytest.param(
        v1001.ResourcePacksInfoPacket(
            resource_pack_required=True,
            has_scripts=True,
            world_template_id_and_version=WORLD_TEMPLATE,
            resource_packs=[PACK],
        ),
        V1001,
        id="v1001-with-pack",
    ),
    pytest.param(
        v1001.ResourcePacksInfoPacket(world_template_id_and_version=WORLD_TEMPLATE),
        V1001_EMPTY,
        id="v1001-empty",
    ),
    pytest.param(
        v2168.ResourcePacksInfoPacket(
            resource_pack_required=True,
            has_scripts=True,
            world_template_id_and_version=WORLD_TEMPLATE,
            resource_packs=[PACK],
        ),
        V2168,
        id="v2168-with-pack",
    ),
    pytest.param(
        v2168.ResourcePacksInfoPacket(world_template_id_and_version=WORLD_TEMPLATE),
        V2168_EMPTY,
        id="v2168-empty",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_packs_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_packs_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("older", "newer"),
    [pytest.param(V1001, V2168, id="with-pack"), pytest.param(V1001_EMPTY, V2168_EMPTY, id="empty")],
)
def test_2168_is_one_byte_shorter_for_the_pack_count(older, newer):
    assert len(older) == len(newer) + 1


def test_2168_changes_only_the_pack_count_width():
    assert V1001[:26] == V2168[:26]
    assert V1001[28:] == V2168[27:]


@pytest.mark.parametrize(
    ("version", "wire"),
    [
        pytest.param(v2168, V1001, id="v2168-reads-v1001"),
        pytest.param(v1001, V2168, id="v1001-reads-v2168"),
        pytest.param(v1001, V2168_EMPTY, id="v1001-reads-v2168-empty"),
    ],
)
def test_decode_rejects_the_other_era_body(version, wire):
    with pytest.raises(ValueError, match="at byte"):
        version.ResourcePacksInfoPacket.from_bytes(wire)


def test_an_empty_1001_body_leaves_a_byte_over_at_2168():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2168.ResourcePacksInfoPacket.from_bytes(V1001_EMPTY)
